// 极致了API配置
const CONFIG = {
  accountName: '饼干哥哥AGI',
  apiKey: 'JZLdc9670be1403c05c',
  baseUrl: 'https://www.dajiala.com/fbmain/monitor/v3/post_history',
  maxPages: 5,      // 每次抓5页
  delayMs: 2000     // 2秒间隔
};

// 飞书机器人配置（需要你填写）
const FEISHU_CONFIG = {
  webhookUrl: 'YOUR_WEBHOOK_URL_HERE',  // 飞书机器人Webhook地址
  secret: 'YOUR_SECRET_HERE'             // 飞书机器人Secret（如果有）
};

return [{
  json: {
    config: CONFIG,
    feishu: FEISHU_CONFIG,
    currentPage: 1,
    allArticles: [],
    totalCost: 0
  }
}];

const response = $input.first().json;

if (response.code !== 0) {
  if (response.code === 110 || response.code === 115) {
    return [{json: {...$input.first().json, hasMore: false}}];
  }
  throw new Error(`API错误: ${response.msg}`);
}

const articles = response.data || [];
const totalPage = response.total_page || 1;
const currentPage = $input.first().json.currentPage;
const allArticles = $input.first().json.allArticles || [];
const maxPages = $input.first().json.config.maxPages;

// 去重
const existingIds = new Set(allArticles.map(a => a.appmsgid));
const newArticles = articles.filter(a => !existingIds.has(a.appmsgid));
allArticles.push(...newArticles);

const hasMore = currentPage < Math.min(totalPage, maxPages);

console.log(`第 ${currentPage} 页: ${newArticles.length} 篇新文章，累计 ${allArticles.length} 篇`);

return [{
  json: {
    ...$input.first().json,
    articles: newArticles,
    allArticles,
    totalPages: totalPage,
    hasMore,
    nextPage: currentPage + 1,
    remainMoney: response.remain_money,
    totalCost: ($input.first().json.totalCost || 0) + (response.cost_money || 0)
  }
}];

// 生成飞书消息卡片
const data = $input.first().json;
const articles = data.allArticles;

// 按日期分组
const grouped = {};
articles.forEach(article => {
  const date = article.post_time_str.split(' ')[0];
  if (!grouped[date]) grouped[date] = [];
  grouped[date].push(article);
});

// 生成消息内容（限制长度）
let content = '';
const sortedDates = Object.keys(grouped).sort((a, b) => new Date(b) - new Date(a)).slice(0, 5);

sortedDates.forEach(date => {
  content += `\n**${date}**\n`;
  grouped[date].slice(0, 3).forEach((article, idx) => {
    content += `${idx + 1}. [${article.title}](${article.url})\n`;
  });
  if (grouped[date].length > 3) {
    content += `...还有 ${grouped[date].length - 3} 篇文章\n`;
  }
});

const message = {
  msg_type: 'interactive',
  card: {
    config: {wide_screen_mode: true},
    header: {
      title: {
        tag: 'plain_text',
        content: `📰 饼干哥哥AGI - 文章监控报告`
      },
      template: 'blue'
    },
    elements: [
      {
        tag: 'div',
        text: {
          tag: 'lark_md',
          content: `**抓取时间:** ${new Date().toLocaleString()}\n**文章总数:** ${articles.length} 篇\n**总费用:** ${data.totalCost.toFixed(2)} 元\n**账户余额:** ${data.remainMoney} 元`
        }
      },
      {tag: 'hr'},
      {
        tag: 'div',
        text: {
          tag: 'lark_md',
          content: content || '暂无文章'
        }
      }
    ]
  }
};

return [{
  json: {
    ...data,
    message,
    webhookUrl: data.feishu.webhookUrl
  }
}];
